import csv, math, datetime, json
rows=list(csv.DictReader(open("data.csv")))
d={}
for r in rows:
    d.setdefault(r["band"],[]).append((datetime.date.fromisoformat(r["date"]),float(r["y"])))
def design(t,t0):
    doy=t.timetuple().tm_yday; x=(t-t0).days
    return [1,x]+[f(2*math.pi*k*doy/365.25) for k in (1,2,3) for f in (math.sin,math.cos)]
def lstsq(A,b):
    n=len(A[0]); M=[[sum(A[i][r]*A[i][c] for i in range(len(A))) for c in range(n)]+[sum(A[i][r]*b[i] for i in range(len(A)))] for r in range(n)]
    for i in range(n):
        p=max(range(i,n),key=lambda r:abs(M[r][i])); M[i],M[p]=M[p],M[i]
        for r in range(n):
            if r!=i:
                f=M[r][i]/M[i][i]
                for c in range(i,n+1): M[r][c]-=f*M[i][c]
    return [M[i][n]/M[i][i] for i in range(n)]
betas={}
for band,series in d.items():
    series.sort(); t0=series[0][0]
    betas[band]=lstsq([design(t,t0) for t,y in series],[y for t,y in series])
    betas[band+"_t0"]=t0
pred={}
for r in csv.DictReader(open("visits_to_predict.csv")):
    t=datetime.date.fromisoformat(r["date"])
    pred[r["period_id"]]={band: round(sum(c*z for c,z in zip(design(t,betas[band+"_t0"]),betas[band])),6) for band in d}
json.dump({"prediction":pred,"rationale":"Single parcel, no cross-sectional controls, so I used the parcel's own 220-visit history (2020-09 to 2024-09) for VH, VV and VV-VH. The series show clear annual seasonality with negligible trend, so I fitted per-band harmonic regressions (linear trend + annual, semi-annual and third-harmonic sin/cos terms on day-of-year) by least squares. In-sample RMSE: VH 0.58, VV 0.55, VV-VH 0.29 dB, i.e. well under the band ranges, so the fits are credible. Predictions for each of the 51 target visits are the fitted values at each visit date."},open("answer.json","w"),indent=1)
print(list(pred.items())[:2]); print(len(pred))
