import csv, datetime, statistics, math, json
rows=list(csv.DictReader(open("data.csv")))
data={}
for r in rows:
    d=datetime.date.fromisoformat(r["date"])
    data.setdefault(r["band"],[]).append((d,float(r["y"])))
for b in data: data[b].sort()

# seasonal climatology: for each target date, weighted avg of historical obs by day-of-year distance (circular, gaussian kernel ~10 days)
def doy(d): return d.timetuple().tm_yday
targets=[(r["period_id"], datetime.date.fromisoformat(r["date"])) for r in csv.DictReader(open("visits_to_predict.csv"))]
pred={}
for b,ts in data.items():
    doys=[doy(d) for d,_ in ts]; vals=[v for _,v in ts]
    for pid,d in targets:
        t=doy(d); h=12.0
        num=den=0.0
        for dy,v in zip(doys,vals):
            dist=abs(t-dy); dist=min(dist,366-dist)
            w=math.exp(-(dist/h)**2)
            num+=w*v; den+=w
        pred.setdefault(pid,{})[b]=num/den

# sanity: LOO check on last year of history
errs={b:[] for b in data}
for b,ts in data.items():
    for i,(d,v) in enumerate(ts):
        if d.year<2024: continue
        t=doy(d); h=12.0; num=den=0.0
        for j,(d2,v2) in enumerate(ts):
            if j>=i: continue
            dist=abs(t-doy(d2)); dist=min(dist,366-dist)
            w=math.exp(-(dist/h)**2); num+=w*v2; den+=w
        errs[b].append(abs(num/den-v))
for b,e in errs.items(): print(b,"LOO MAE 2024:",round(statistics.mean(e),3),"n",len(e))
json.dump(pred,open("pred_tmp.json","w"))
print("P221",pred["P221"]); print("P271",pred["P271"])
