        return sum((res[i]-m)*(res[i+k]-m) for i in range(n-k))/sum((x-m)**2 for x in res)
    print(b, "res sd", round(statistics.stdev(res),3), "ac1", round(ac(1),3), "ac2", round(ac(2),3), "ac3", round(ac(3),3))
