import csv, collections, datetime, json
rows=list(csv.DictReader(open("data.csv")))
d=collections.defaultdict(list)
for r in rows: d[r["band"]].append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
targets=[(r["period_id"], datetime.date.fromisoformat(r["date"])) for r in csv.DictReader(open("visits_to_predict.csv"))]
pred={}
for pid,dt in targets:
    pred[pid]={}
    for b,v in d.items():
        # seasonal matches: same day-of-year +/-10 days, from observed history
        matches=[]
        for d2,y2 in v:
            dd=abs((d2-dt).days)%365
            dd=min(dd,365-dd)
            if dd<=10: matches.append((d2,y2))
        matches.sort(reverse=True)  # most recent first
        use=[y for _,y in matches[:6]]  # up to ~2 most recent years of visits
        pred[pid][b]=round(sum(use)/len(use),6)
json.dump(pred,open("preds_seasonal.json","w"),indent=1)
print(json.dumps({k:pred[k] for k in list(pred)[:3]},indent=1))
print(json.dumps({k:pred[k] for k in list(pred)[-3:]},indent=1))
