import csv, datetime, statistics, json, math
rows=list(csv.DictReader(open("data.csv")))
series={}
for r in rows:
    series.setdefault(r["band"],[]).append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
targets=[(r["period_id"], datetime.date.fromisoformat(r["date"])) for r in csv.DictReader(open("visits_to_predict.csv"))]

def doy(d): return d.timetuple().tm_yday
def climatology(s, d, halfwin=20):
    t=doy(d)
    vals=[]
    for dd,v in s:
        diff=abs(((dd-d).days)%365)
        diff=min(diff,365-diff)
        if diff<=halfwin: vals.append(v)
    return statistics.mean(vals), len(vals)

pred={}
for pid,d in targets:
    pred[pid]={}
    for b,s in series.items():
        v,n=climatology(s,d)
        pred[pid][b]=round(v,4)

# sanity: leave-one-out check of climatology method
errs={b:[] for b in series}
for b,s in series.items():
    for i,(d,v) in enumerate(s):
        rest=s[:i]+s[i+1:]
        p,_=climatology(rest,d)
        errs[b].append(abs(p-v))
print({b:round(statistics.mean(e),3) for b,e in errs.items()})

json.dump({"prediction":pred,"rationale":"Seasonal climatology: each band's history (117 visits, 2020-09 to 2024-09) shows a stable, repeating annual cycle with no trend (yearly means flat). For each target visit, each band's mean is estimated as the average of historical observations within +/-20 days of the same day of year. Leave-one-out MAE of this estimator: VH ~0.5 dB, VV ~0.3 dB, VV-VH ~0.4 dB."}, open("answer.json","w"), indent=1)
print("written")
