import csv, json, statistics
rows=list(csv.DictReader(open('data.csv')))
H={}
for r in rows: H.setdefault(r['band'],[]).append(float(r['y']))
n=len(H['VH'])
shc=json.load(open('preds.json')); sn=json.load(open('snaive.json'))
# backtest on last 26 points
for name,P in [('shc',shc),('snaive',sn)]:
    errs=[]
    for h in range(1,27):
        idx=n-h
        for b in H: errs.append(P[str(h)][b]-H[b][idx])
    print(name, 'MAE', round(statistics.mean(abs(e) for e in errs),3), 'bias', round(statistics.mean(errs),3))
# ensemble
errs=[]
for h in range(1,27):
    idx=n-h
    for b in H: errs.append(0.5*(shc[str(h)][b]+sn[str(h)][b])-H[b][idx])
print('ens MAE', round(statistics.mean(abs(e) for e in errs),3))
