import csv, collections, datetime, statistics, math
rows=list(csv.DictReader(open("data.csv")))
per=collections.defaultdict(dict); dates={}
for r in rows:
    per[r["period_id"]][r["band"]]=float(r["y"])
    dates[r["period_id"]]=r["date"]
ids=sorted(per)
ds=[datetime.date.fromisoformat(dates[i]) for i in ids]
bands=sorted(per[ids[0]])
def pred(band, d, W, exclude_idx):
    vals=[]
    for j,(i,dj) in enumerate(zip(ids,ds)):
        if j==exclude_idx: continue
        dd=abs((d-dj).days)%365
        dd=min(dd,365-dd)
        if dd<=W: vals.append(per[i][band])
    return statistics.mean(vals) if vals else None
for W in [10,20,30]:
    for b in bands:
        errs=[]
        for j,(i,d) in enumerate(zip(ids,ds)):
            if j<20: continue
            p=pred(b,d,W,j)
            errs.append(abs(p-per[i][b]))
        print(W,b,round(statistics.mean(errs),2))
    print()
def predw(band,d,h,exclude_idx):
    num=den=0
    for j,(i,dj) in enumerate(zip(ids,ds)):
        if j==exclude_idx: continue
        dd=abs((d-dj).days)%365; dd=min(dd,365-dd)
        w=math.exp(-(dd/h)**2)
        num+=w*per[i][band]; den+=w
    return num/den
for h in [7,10,15,20]:
    tot=[]
    for j,(i,d) in enumerate(zip(ids,ds)):
        if j<20: continue
        for b in bands:
            tot.append(abs(predw(b,d,h,j)-per[i][b]))
    print("gauss h",h,round(statistics.mean(tot),2))
