rows=list(csv.DictReader(open("data.csv")))
data=collections.defaultdict(dict); dates={}
for r in rows:
    data[r["band"]][r["period_id"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
periods=sorted(dates, key=lambda p:dates[p])
clear=[p for p in periods if data["NDVI"][p]>0.3 and data["B2"][p]<1500]
D={p:datetime.date.fromisoformat(dates[p]) for p in clear}

def seasonal_loo(p, band, win=20):
    t=D[p]; doy=t.timetuple().tm_yday
    # neighbors: same doy window, other years; detrend by per-year mean of band
    yrs=sorted(set(D[q].year for q in clear))
    ymean={y:statistics.mean(data[band][q] for q in clear if D[q].year==y) for y in yrs}
    num=den=0.0
    for q in clear:
        if q==p: continue
        dq=D[q]; dd=abs((dq.timetuple().tm_yday-doy+182)%365-182)
        if dd<=win and dq.year!=t.year:
            w=1-(dd/win)**2
            num+=w*(data[band][q]-ymean[dq.year]); den+=w
    if den==0: return None
    return ymean[t.year]+num/den

for band in data:
    errs=[]
    for p in clear:
        if D[p].year==2020: continue
        pr=seasonal_loo(p,band)
        if pr is not None: errs.append(abs(pr-data[band][p]))
    print(band,"LOO MAE",round(statistics.mean(errs),3),"n",len(errs))
