import csv, collections, datetime, statistics, math, json
rows=list(csv.DictReader(open('data.csv')))
by_p=collections.defaultdict(dict); dates={}
for r in rows:
    by_p[r['period_id']][r['band']]=float(r['y'])
    dates[r['period_id']]=datetime.date.fromisoformat(r['date'])
ps=sorted(by_p)
bands=sorted(next(iter(by_p.values())).keys())

def doy(d): return d.timetuple().tm_yday
def dwrap(a,b): return min(abs(a-b),365-abs(a-b))

def predict(band, target, window, trend):
    # historical points within window days of target's day-of-year
    cand=[(dates[p], by_p[p][band]) for p in ps if dwrap(doy(dates[p]),doy(target))<=window]
    if not cand: return None
    if trend:
        # linear in time (years) fit
        xs=[(d-target).days/365.25 for d,v in cand]; ys=[v for d,v in cand]
        n=len(xs); mx=sum(xs)/n; my=sum(ys)/n
        sxx=sum((x-mx)**2 for x in xs); sxy=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
        b=sxy/sxx if sxx>0 else 0
        return my + b*(0-mx)
    return statistics.mean(v for d,v in cand)

# LOOCV over history
for window in [5,10,15,20,25]:
    for trend in [False,True]:
        errs=collections.defaultdict(list)
        for p in ps:
            t=dates[p]
            cand=[q for q in ps if q!=p and dwrap(doy(dates[q]),doy(t))<=window]
            if not cand: continue
            for band in bands:
                xs=[(dates[q]-t).days/365.25 for q in cand]; ys=[by_p[q][band] for q in cand]
                if trend:
                    n=len(xs); mx=sum(xs)/n; my=sum(ys)/n
                    sxx=sum((x-mx)**2 for x in xs); sxy=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
                    b=sxy/sxx if sxx>0 else 0
                    pred=my+b*(0-mx)
                else: pred=statistics.mean(ys)
                errs[band].append(abs(pred-by_p[p][band]))
        tot=sum(statistics.mean(v) for v in errs.values())/len(bands)
        print(window,trend,round(tot,3))
