pids=sorted(dates)
ds={p:datetime.date.fromisoformat(dates[p]) for p in pids}

def feats(d):
    a=2*math.pi*d.timetuple().tm_yday/365.25
    return [1,math.sin(a),math.cos(a),math.sin(2*a),math.cos(2*a),d.year]

def lstsq(F,y):
    n=len(F[0])
    A=[[sum(f[i]*f[j] for f in F) for j in range(n)] for i in range(n)]
    b=[sum(f[i]*v for f,v in zip(F,y)) for i in range(n)]
    x=[0]*n
    for i in range(n):
        piv=max(range(i,n),key=lambda r:abs(A[r][i])); A[i],A[piv]=A[piv],A[i]; b[i],b[piv]=b[piv],b[i]
        for r in range(i+1,n):
            f=A[r][i]/A[i][i]
            for c in range(i,n): A[r][c]-=f*A[i][c]
            b[r]-=f*b[i]
    for i in range(n-1,-1,-1):
        x[i]=(b[i]-sum(A[i][j]*x[j] for j in range(i+1,n)))/A[i][i]
    return x

