    idx=list(pids)
    for _ in range(3):
        F=[feats(ds[p]) for p in idx]; y=[per[band][p] for p in idx]
        c=lstsq(F,y)
        res={p: per[band][p]-sum(a*v for a,v in zip(c,feats(ds[p]))) for p in idx}
